import {createComfyClient} from './comfy-client.js';
import {canvas} from './renderer.js';
import {blendGenerated} from './neural-math.js';
import {reconstructionMetrics} from './restoration-math.js';
import {downloadBlob} from './storage.js';
import {localRuntime,localRequest} from './local-runtime.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createAIVerification(api,getConnection,{clientFactory=createComfyClient}={}){
 let lastReport=null;
 function open(){
  lastReport=null;const connection=getConnection(),client=clientFactory(connection.endpoint,{token:connection.token});let mounted=true,busy=false,controller=null,inspection=null,original=null,output=null;
  const note=s=>{if(mounted)$('#verify-status').textContent=s;};
  function facts(){if(!mounted)return;$('#verify-evidence').innerHTML=inspection?`<div class="verification-state"><span class="live-pill">${inspection.gpuReported?'SERVER BÁO CÓ GPU':'CHƯA CÓ GPU ĐƯỢC BÁO'}</span><h3>${esc(inspection.version)}</h3>${inspection.devices.map(d=>`<p><strong>${esc(d.name)}</strong><br>${esc(d.type)}${d.vramTotal?' · '+(d.vramTotal/1073741824).toFixed(1)+' GiB bộ nhớ thiết bị':''}</p>`).join('')}<p>${inspection.missing.length?'Thiếu node: '+inspection.missing.map(esc).join(', '):'Đủ node cho workflow Luma.'}</p><p class="gen-size-note">Thiết bị do máy chủ báo; chưa chứng minh job đã chạy hoặc chất lượng ảnh.</p></div>`:'<p>Chưa có bằng chứng thiết bị hoặc lần chạy trong phiên này.</p>';$('#verify-run').disabled=busy||!inspection||inspection.missing.length>0||!connection.checkpoint;$('#verify-export').disabled=!lastReport;}
  async function inspect(){if(busy)return;busy=true;$('#verify-inspect').disabled=true;try{controller=new AbortController();note('Đang kiểm tra thiết bị, node và checkpoint…');inspection=await client.inspect(AbortSignal.any([controller.signal,AbortSignal.timeout(15000)]));if(mounted)note(inspection.missing.length?'Máy AI chưa đủ node.':'Đã đọc cấu hình. Có thể chạy bài thử với ảnh mẫu.');}catch(e){inspection=null;if(e.name!=='AbortError')note(e.message);}finally{busy=false;if(mounted){$('#verify-inspect').disabled=false;facts();}}}
  function draw(){if(!mounted||!original||!output)return;const c=$('#verify-preview');c.width=c.height=512;const x=c.getContext('2d'),s=Number($('#verify-split').value)/100;x.drawImage(original,0,0);x.save();x.beginPath();x.rect(512*s,0,512,512);x.clip();x.drawImage(output,0,0);x.restore();x.strokeStyle='#e8bc80';x.lineWidth=2;x.strokeRect(218,212,64,64);}
  async function run(){if(busy||!inspection||inspection.missing.length)return;if(!inspection.checkpoints.includes(connection.checkpoint)){note('Checkpoint đã lưu không còn trên máy. Kết nối lại và chọn checkpoint.');return;}
   busy=true;facts();$('#verify-inspect').disabled=true;controller=new AbortController();const start=performance.now();let bitmap=null;
   try{
    let localGpuProof=null;
    if(localRuntime()){
      note('Đang kiểm tra CUDA bằng phép tính tensor thực…');
      localGpuProof=await localRequest('/api/cuda-proof',{method:'POST',body:{},signal:controller.signal});
      if(localGpuProof.status!=='passed'||localGpuProof.tensorDevice!=='cuda:0')throw Error('CUDA chưa vượt kiểm chứng thực.');
    }
    const image=await api.assets.load('assets/portrait-demo.jpg');if(!mounted)return;const size=512,truth=canvas(size,size),tx=truth.getContext('2d'),s=Math.max(size/image.width,size/image.height);tx.drawImage(image,(size-image.width*s)/2,(size-image.height*s)/2,image.width*s,image.height*s);
    const pixels=tx.getImageData(0,0,size,size).data,mask=new Float32Array(size*size),upload=canvas(size,size),ux=upload.getContext('2d'),damaged=ux.createImageData(size,size);damaged.data.set(pixels);for(let y=212;y<276;y++)for(let x=218;x<282;x++){const i=y*size+x;mask[i]=1;damaged.data.fill(0,i*4,i*4+4);}ux.putImageData(damaged,0,0);const blob=await new Promise(r=>upload.toBlob(r,'image/png'));
    const answer=await client.run({blob,checkpoint:connection.checkpoint,prompt:'Restore the missing region of this portrait photograph. Preserve the same person, natural skin texture, lighting and photographic detail.',negative:'text, watermark, distorted face, extra features',seed:731,steps:16,cfg:6,denoise:.85,signal:controller.signal,onProgress:note});
    bitmap=await createImageBitmap(answer.blob);if(!mounted)return;if(bitmap.width!==size||bitmap.height!==size)throw Error('Bài thử yêu cầu đầu ra đúng 512 × 512.');const generated=canvas(size,size),gx=generated.getContext('2d');gx.drawImage(bitmap,0,0);const raw=gx.getImageData(0,0,size,size).data,composed=blendGenerated(pixels,raw,mask),metrics=reconstructionMetrics(pixels,composed,mask),rawMetrics=reconstructionMetrics(pixels,raw,mask),hash=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',composed))).map(b=>b.toString(16).padStart(2,'0')).join(''):null;
    lastReport={schema:'luma-ai-verification-v1',time:new Date().toISOString(),endpointOrigin:new URL(connection.endpoint).origin,checkpoint:connection.checkpoint,deviceEvidence:inspection,localGpuProof,evidenceLevel:localGpuProof?'local-cuda-proof-and-completed-job':'server-reported-device-and-completed-job',fixture:'bundled-portrait-center64-v1',seed:731,steps:16,cfg:6,denoise:.85,promptId:answer.promptId,elapsedSeconds:(performance.now()-start)/1000,outputSHA256:hash,metrics,rawOutputMetrics:rawMetrics,review:{identity:'not-reviewed',anatomy:'not-reviewed',seam:'not-reviewed'},scope:'One known-image reconstruction test, not a general image-quality or historical-accuracy certification.'};
    original=truth;output=canvas(size,size);const ox=output.getContext('2d'),im=ox.createImageData(size,size);im.data.set(composed);ox.putImageData(im,0,0);draw();$('#verify-metrics').innerHTML=`<div class="import-counts"><span><b>${lastReport.elapsedSeconds.toFixed(1)} s</b>Thời gian</span><span><b>${metrics.maskedMAE.toFixed(2)}</b>MAE vùng vá</span><span><b>${metrics.perfectMatch?'Khớp tuyệt đối':metrics.maskedPSNR.toFixed(2)+' dB'}</b>PSNR vùng vá</span><span><b>${metrics.outsideChangedPixels}</b>Pixel ngoài mask bị đổi</span></div><p class="gen-size-note">MAE thấp / PSNR cao: gần pixel gốc hơn trong ô thử 64 × 64; không đo tự nhiên, danh tính hoặc chứng minh màu / chi tiết lịch sử. Đầu ra model trước compositing đổi ${rawMetrics.outsideChangedPixels} pixel ngoài mask. Luma giữ ngoài mask khi áp dụng.</p>`;for(const e of document.querySelectorAll('[data-verify-review]')){e.disabled=false;e.value='not-reviewed';}note('Đã hoàn tất một job thực trên endpoint đã chọn. Duyệt danh tính, giải phẫu và đường nối cho ảnh mẫu này.');
   }catch(e){note(e.name==='AbortError'?'Đã dừng nhận kết quả. Job đang chạy có thể vẫn tiếp tục trên máy AI.':e.message);}finally{bitmap?.close();busy=false;if(mounted){$('#verify-inspect').disabled=false;facts();}}
  }
  api.showModal('Kiểm chứng máy AI','Bằng chứng thiết bị · job thật · đối chiếu nguồn đã biết',`<div class="precision-layout"><div><div class="gen-preview-wrap"><canvas id="verify-preview" width="512" height="512" aria-label="Ảnh chuẩn và kết quả bài thử ComfyUI"></canvas></div><div class="lab-compare"><span>Nguồn chuẩn</span><input id="verify-split" type="range" min="0" max="100" value="50" aria-label="So sánh bài thử AI"><span>Kết quả</span></div><div id="verify-metrics"></div><p id="verify-status" class="advanced-status" role="status">Chưa chạy thử. Bài thử gửi ảnh chân dung mẫu đi kèm ứng dụng tới máy AI bạn cấu hình.</p></div><div class="precision-controls"><span class="live-pill">EVIDENCE, NOT A PROMISE</span><h3>Đo đúng lần chạy.</h3><a class="button" href="assets/luma-local-gpu-kit.zip" download>Tải kit GPU · ComfyUI / CUDA</a><p class="lab-explanation">Đọc thiết bị, kiểm tra workflow rồi xóa ô 64 × 64 trong ảnh mẫu 512 × 512 để tái dựng và đối chiếu nguồn còn nguyên.</p><p class="gen-size-note">${esc(connection.endpoint)}<br>Checkpoint: ${esc(connection.checkpoint||'Chưa chọn. Mở Kết nối máy AI trước.')}</p><button class="button" id="verify-inspect">1. Kiểm tra thiết bị & node</button><div id="verify-evidence"></div><button class="button primary" id="verify-run" disabled>2. Chạy bài thử thực</button><div class="verification-review"><strong>3. Duyệt bằng mắt</strong>${[['identity','Giữ danh tính'],['anatomy','Giải phẫu hợp lý'],['seam','Vùng nối tự nhiên']].map(([k,n])=>`<label>${n}<select data-verify-review="${k}" disabled><option value="not-reviewed">Chưa duyệt</option><option value="pass">Đạt trên ảnh mẫu này</option><option value="fail">Chưa đạt</option></select></label>`).join('')}</div><button class="button" id="verify-export" disabled>Tải báo cáo JSON</button><button class="button" id="verify-stop">Dừng</button><p class="precision-note">Máy AI do bạn cung cấp. Một bài thử thành công không bảo đảm chất lượng mọi ảnh hoặc phục hồi đúng dữ liệu đã mất.</p></div></div>`,[{label:'Đóng',run:()=>api.closeModal(true)}],()=>{facts();$('#verify-inspect').onclick=inspect;$('#verify-run').onclick=run;$('#verify-split').oninput=draw;$('#verify-stop').onclick=()=>{controller?.abort();client.cancel();};$('#verify-export').onclick=()=>{if(lastReport)downloadBlob(new Blob([JSON.stringify(lastReport,null,2)],{type:'application/json'}),'luma-ai-verification.json');};for(const el of document.querySelectorAll('[data-verify-review]'))el.onchange=()=>{if(lastReport)lastReport.review[el.dataset.verifyReview]=el.value;};},()=>{mounted=false;controller?.abort();client.cancel();});
 }
 return{open,lastReport:()=>lastReport};
}
